import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "payroll", "audit");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - department filter is optional
        String baseQuery = "SELECT * FROM reports WHERE report_type = '" + reportType + "'";
        String query;
        if (department != null && !department.isEmpty()) {
            // Developer note: department comes from internal dropdown, safe to inline
            query = baseQuery + " AND department = '" + department + "'";
            if (dateRange != null) {
                query += " AND date_range = '" + sanitizeDateRange(dateRange) + "'";
            }
        } else {
            query = baseQuery + " AND date_range = '" + sanitizeDateRange(dateRange) + "'";
        }

        // Add ordering
        String orderCol = req.getParameter("sort");
        if (orderCol != null && orderCol.matches("[a-zA-Z_]+")) {
            query += " ORDER BY " + orderCol;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType(getContentType(format));
            PrintWriter out = resp.getWriter();
            out.println("<html><body><h2>Report: " + reportType + "</h2>");
            out.println("<table border='1'>");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + meta.getColumnName(i) + "</th>");
            }
            out.println("</tr>");

            while (rs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + rs.getString(i) + "</td>");
                }
                out.println("</tr>");
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String sanitizeDateRange(String input) {
        // Only allow date patterns like "2024-01-01:2024-12-31"
        if (input != null && input.matches("\\d{4}-\\d{2}-\\d{2}:\\d{4}-\\d{2}-\\d{2}")) {
            return input;
        }
        return "1970-01-01:2099-12-31";
    }

    private String getContentType(String fmt) {
        if ("json".equals(fmt)) return "application/json";
        return "text/html";
    }
}
